{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "GSK1322322, a structurally similar heteroaryl-amine with a piperazine and aniline-pyrimidine motif, showed 77% absolute oral bioavailability in healthy volunteers after a meal, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Brepocitinib, a kinase inhibitor with an aminopyrimidine and saturated N-heterocycle, had 75% absolute oral bioavailability in humans, supporting high F for the query's heteroaryl-amine/piperazine-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Imatinib, which contains a piperazine and aminopyrimidine, had a mean absolute oral bioavailability of 98%, indicating that piperazine-containing heteroaryl amines can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Risdiplam, a fused heteroaromatic with a piperazine and high oral F, showed complete absorption and negligible first-pass extraction, supporting high oral bioavailability for the query's fused heteroaromatic-piperazine structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "A compound with an N-cyclopentyl-substituted fused heteroaromatic was predicted to have 80% human oral bioavailability, supporting the high-F contribution of the cyclopentyl-substituted heterocycle in the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is a heteroaromatic amine with a piperazine and N-cyclopentyl substituent. Multiple structurally similar molecules—GSK1322322, brepocitinib, imatinib, risdiplam, and a cyclopentyl-containing analogue—show absolute oral bioavailability well above the 20% threshold (57–98%). No relevant evidence suggests F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the exact query molecule.",
    "Some supporting records are from predicted human pharmacokinetics rather than measured absolute bioavailability studies.",
    "The closest analogues differ in ionization, solubility, and metabolic clearance, so exact F may vary, but all remain far above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

